//! Token generation shared by the chat and completion routes.
//!
//! Requests are generated by a per-model [`Engine`](skelm_exec::Engine)
//! (batched with the other requests, reusing cached prompt prefixes), or one
//! at a time on a fresh context for models with speculative decoding. Both
//! report tokens to an [`ApiSink`], which adds what the API surface needs —
//! `stop` sequences and incremental UTF-8-safe decoding for streaming — and
//! sends [`GenEvent`]s to the route.

use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender};

use skelm_exec::{Context, Flow, JobEnd, JobEvent, JobSink};
use skelm_llama_cpp::{
    SamplerChain, SamplerDistance, SamplerGreedy, SamplerMinP, SamplerTemperature,
};

use crate::error::ApiError;

/// Sampling / stopping knobs distilled from a request.
#[derive(Debug, Clone, Default)]
pub struct GenConfig {
    pub temperature: Option<f32>,
    pub seed: Option<u32>,
    pub max_tokens: Option<usize>,
    pub stop: Vec<String>,
}

/// Why generation ended.
#[derive(Debug, Clone, Copy)]
pub enum FinishReason {
    /// End-of-generation token, a stop sequence, or client cancellation.
    Stop,
    /// The `max_tokens` cap was reached, or the context is full.
    Length,
}

impl FinishReason {
    pub fn as_str(self) -> &'static str {
        match self {
            FinishReason::Stop => "stop",
            FinishReason::Length => "length",
        }
    }
}

pub struct GenResult {
    /// The full generated text, with any trailing stop sequence removed.
    pub text: String,
    pub prompt_tokens: usize,
    /// Prompt tokens reused from the cache instead of being processed.
    pub cached_tokens: usize,
    /// Number of tokens sampled (including control tokens).
    pub completion_tokens: usize,
    pub finish_reason: FinishReason,
}

/// What a generation sends to its route
pub enum GenEvent {
    /// newly finalized text (never partial UTF-8, never a partial stop sequence)
    Text(String),
    /// the generation is over
    Done(GenResult),
    /// the generation failed (nothing follows)
    Error(ApiError),
}

/// Wait for the end of a generation, for a non-streaming response
pub async fn collect(mut events: UnboundedReceiver<GenEvent>) -> Result<GenResult, ApiError> {
    while let Some(event) = events.recv().await {
        match event {
            GenEvent::Text(_) => {}
            GenEvent::Done(result) => return Ok(result),
            GenEvent::Error(e) => return Err(e),
        }
    }
    Err(ApiError::Internal("the generation was aborted".into()))
}

/// Build the sampler chain for a request.
///
/// `temperature <= 0` selects greedy decoding; otherwise we use the same
/// min-p + temperature + distribution chain as the CLI default, seeded by the
/// request (or llama.cpp's default seed).
pub fn build_sampler(cfg: &GenConfig) -> SamplerChain {
    let mut chain = SamplerChain::new();
    let temperature = cfg.temperature.unwrap_or(0.8);
    let seed = cfg.seed.unwrap_or(0xFFFF_FFFF);

    if temperature <= 0.0 {
        chain.add(Box::new(SamplerGreedy));
    } else {
        chain.add(Box::new(SamplerMinP::new(0.05, 1)));
        chain.add(Box::new(SamplerTemperature::new(temperature)));
        chain.add(Box::new(SamplerDistance::new(seed)));
    }
    chain
}

/// Byte offset of the earliest stop-sequence match in `s`, if any.
fn earliest_stop(s: &str, stops: &[String]) -> Option<usize> {
    stops
        .iter()
        .filter(|stop| !stop.is_empty())
        .filter_map(|stop| s.find(stop.as_str()))
        .min()
}

/// Length (in bytes) of the longest suffix of `s` that is a *strict* prefix of
/// some stop sequence. Those trailing bytes are held back from streaming until
/// we know whether they complete a stop sequence, so partial markers never leak.
fn holdback_len(s: &str, stops: &[String]) -> usize {
    let mut max = 0usize;
    for stop in stops {
        if stop.is_empty() {
            continue;
        }
        // A full match is handled by `earliest_stop`; only prefixes shorter than
        // the whole stop matter here.
        let upper = (stop.len() - 1).min(s.len());
        let mut k = upper;
        while k >= 1 {
            let s_start = s.len() - k;
            if stop.is_char_boundary(k)
                && s.is_char_boundary(s_start)
                && s.as_bytes()[s_start..] == stop.as_bytes()[..k]
            {
                max = max.max(k);
                break;
            }
            k -= 1;
        }
    }
    max
}

/// The valid-UTF-8 prefix of `bytes` as a `&str` (tokens can split a codepoint,
/// so the trailing incomplete bytes are excluded until completed).
fn valid_prefix(bytes: &[u8]) -> &str {
    let valid = match std::str::from_utf8(bytes) {
        Ok(s) => return s,
        Err(e) => e.valid_up_to(),
    };
    // `valid` is a char boundary by definition, so this cannot fail.
    std::str::from_utf8(&bytes[..valid]).expect("valid utf8 prefix")
}

/// Turns the tokens of a generation into [`GenEvent`]s
pub struct ApiSink {
    tx: UnboundedSender<GenEvent>,
    stop: Vec<String>,
    n_ctx: usize,
    bytes: Vec<u8>,
    /// byte offset into the decoded text already sent
    emitted: usize,
    prompt_tokens: usize,
    cached_tokens: usize,
    completion_tokens: usize,
    started: bool,
    done: bool,
}

impl ApiSink {
    /// A sink sending to `tx`; `n_ctx` is only used in error messages
    pub fn new(tx: UnboundedSender<GenEvent>, cfg: &GenConfig, n_ctx: usize) -> Self {
        ApiSink {
            tx,
            stop: cfg.stop.clone(),
            n_ctx,
            bytes: Vec::new(),
            emitted: 0,
            prompt_tokens: 0,
            cached_tokens: 0,
            completion_tokens: 0,
            started: false,
            done: false,
        }
    }

    fn send_text(&self, text: &str) {
        if !text.is_empty() {
            let _ = self.tx.send(GenEvent::Text(text.to_string()));
        }
    }

    fn finish(&mut self, text: String, finish_reason: FinishReason) {
        self.done = true;
        let _ = self.tx.send(GenEvent::Done(GenResult {
            text,
            prompt_tokens: self.prompt_tokens,
            cached_tokens: self.cached_tokens,
            completion_tokens: self.completion_tokens,
            finish_reason,
        }));
    }

    fn fail(&mut self, error: ApiError) {
        self.done = true;
        let _ = self.tx.send(GenEvent::Error(error));
    }

    /// A generated token's text; returns whether a stop sequence was reached
    fn push(&mut self, piece: &[u8]) -> bool {
        self.bytes.extend_from_slice(piece);
        let text = valid_prefix(&self.bytes);

        if let Some(cut) = earliest_stop(text, &self.stop) {
            if cut > self.emitted {
                self.send_text(&text[self.emitted..cut]);
            }
            let text = text[..cut].to_string();
            self.finish(text, FinishReason::Stop);
            return true;
        }

        let end = text.len() - holdback_len(text, &self.stop);
        if end > self.emitted {
            self.send_text(&text[self.emitted..end]);
            self.emitted = end;
        }
        false
    }

    /// The generation ended without a stop sequence
    fn end(&mut self, finish_reason: FinishReason) {
        // flush any bytes withheld for a stop sequence that never completed
        let text = valid_prefix(&self.bytes);
        if text.len() > self.emitted {
            self.send_text(&text[self.emitted..]);
        }
        let text = String::from_utf8_lossy(&self.bytes).into_owned();
        self.finish(text, finish_reason);
    }
}

impl JobSink for ApiSink {
    fn event(&mut self, event: JobEvent) -> Flow {
        if self.done {
            return Flow::Stop;
        }
        match event {
            JobEvent::Started {
                prompt_tokens,
                cached_tokens,
            } => {
                self.started = true;
                self.prompt_tokens = prompt_tokens;
                self.cached_tokens = cached_tokens;
            }
            JobEvent::Token { piece, .. } => {
                self.completion_tokens += 1;
                if self.push(&piece) {
                    return Flow::Stop;
                }
            }
            JobEvent::Finished(end) => match end {
                JobEnd::Eog | JobEnd::Stopped => self.end(FinishReason::Stop),
                JobEnd::MaxTokens => self.end(FinishReason::Length),
                JobEnd::ContextFull if !self.started => self.fail(ApiError::BadRequest(format!(
                    "the prompt does not fit in the context ({} tokens)",
                    self.n_ctx
                ))),
                JobEnd::ContextFull => self.end(FinishReason::Length),
                JobEnd::Error(e) => {
                    self.fail(ApiError::Internal(format!("generation failed: {e}")))
                }
            },
        }
        if self.tx.is_closed() {
            Flow::Stop
        } else {
            Flow::Continue
        }
    }

    fn cancelled(&self) -> bool {
        self.tx.is_closed()
    }
}

/// Generate a reply to `prompt` on a fresh `context`, one token step at a time
/// (the path of models with speculative decoding, which the engine doesn't do)
pub fn generate_serial(
    context: &mut Context,
    prompt: &[skelm_llama_cpp::Token],
    cfg: &GenConfig,
    sink: &mut ApiSink,
) {
    let mut sampler = build_sampler(cfg);
    let vocab = context.0.vocab.clone();
    let n_ctx = context.1.n_ctx() as usize;
    if prompt.len() >= n_ctx {
        sink.event(JobEvent::Finished(JobEnd::ContextFull));
        return;
    }
    if let Err(e) = context.1.append_tokens(prompt) {
        sink.event(JobEvent::Finished(JobEnd::Error(e.to_string())));
        return;
    }
    sink.event(JobEvent::Started {
        prompt_tokens: prompt.len(),
        cached_tokens: 0,
    });

    let mut generated = 0;
    let end = 'generation: loop {
        if sink.cancelled() {
            break JobEnd::Stopped;
        }
        if context.1.n_past() >= n_ctx {
            break JobEnd::ContextFull;
        }
        // one token, or several with speculative decoding
        let step = match context.1.step(&mut sampler, &vocab) {
            Ok(step) => step,
            Err(e) => break JobEnd::Error(e.to_string()),
        };
        for token in step.tokens {
            generated += 1;
            let control = vocab.token_attr(token).is_control();
            let piece = if control {
                Vec::new()
            } else {
                vocab.as_bytes(token)
            };
            let event = JobEvent::Token {
                token,
                piece,
                control,
            };
            if sink.event(event) == Flow::Stop {
                break 'generation JobEnd::Stopped;
            }
            if cfg.max_tokens.is_some_and(|max| generated >= max) {
                break 'generation JobEnd::MaxTokens;
            }
        }
        if step.eog {
            break JobEnd::Eog;
        }
    };
    sink.event(JobEvent::Finished(end));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn earliest_stop_finds_first() {
        let stops = vec!["END".to_string(), "STOP".to_string()];
        assert_eq!(earliest_stop("hi STOP there END", &stops), Some(3));
        assert_eq!(earliest_stop("nothing here", &stops), None);
    }

    #[test]
    fn holdback_matches_partial_suffix() {
        let stops = vec!["STOP".to_string()];
        // "...STO" is a strict prefix of "STOP" -> hold back 3 bytes.
        assert_eq!(holdback_len("abcSTO", &stops), 3);
        // A completed match is not a held-back prefix.
        assert_eq!(holdback_len("abcSTOP", &stops), 0);
        // No shared suffix.
        assert_eq!(holdback_len("abcdef", &stops), 0);
    }

    #[test]
    fn valid_prefix_drops_incomplete_codepoint() {
        // "é" is 0xC3 0xA9; a lone leading byte must be withheld.
        assert_eq!(valid_prefix(&[b'a', 0xC3]), "a");
        assert_eq!(valid_prefix(&[b'a', 0xC3, 0xA9]), "aé");
    }
}
